edits.find:
// Gems
for (const pl of platforms) {
  if (!pl.gem) continue;
  const gy = pl.y + pl.gem.position.y;
  if (Math.hypot(p.x - pl.x, p.y + 0.4 - gy, p.z - pl.z) < 0.95) {
    pl.g.remove(pl.gem); pl.gem = null; gems++;
    logEvent("gem", { platform: pl.id, total: gems, height: pl.gem.position.y });
    sfx.gem(); burst(pl.x, gy - 0.1, pl.z, 10, 0.9);
  }
}

